/**
 * Typed loader and runtime validator for the eLux terminal.ini / kioskmode.ini config key
 * schema generated by `scripts/generate-elux-schema.ts` into `schema/elux-config.json`.
 *
 * This is the single source of truth for eLux config keys (§1 of the upgrade spec): defaults,
 * value ranges, since-version, and publish flags, derived from the official Unicon terminal.ini
 * and kioskmode.ini reference documentation. RSoP resolution, pre-write validation, and the
 * `scout://schema/*` MCP resources all read through this module rather than re-parsing JSON.
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { z } from 'zod';

const __dirname = dirname(fileURLToPath(import.meta.url));

// schema/elux-config.json lives at the repo root; this module lives at src/schema/, and after
// build at dist/schema/ — both are one level under the repo root's immediate child directory,
// so '../../schema/elux-config.json' resolves correctly from either src/ (via tsx) or dist/.
const SCHEMA_PATH = join(__dirname, '..', '..', 'schema', 'elux-config.json');

// ── Zod schema for a single entry ──────────────────────────────────────────────

/**
 * Range can be a flat array of literal values (string/number/boolean), a {min,max} numeric
 * bound, or a free-text type hint (e.g. "string", "a URL") when the source documented a type
 * rather than an enumerable set of values.
 */
const RangeSchema = z.union([
  z.array(z.union([z.string(), z.number(), z.boolean()])),
  z.object({ min: z.number(), max: z.number() }),
  z.string(),
  z.null(),
]);

export const EluxConfigEntrySchema = z.object({
  section: z.string().min(1),
  key: z.string().min(1),
  /** Documented default value, or the literal string "unset" when the source has none. */
  default: z.union([z.string(), z.number(), z.boolean(), z.null()]),
  range: RangeSchema,
  sinceVersion: z.string().nullable(),
  publish: z.boolean(),
  notes: z.string(),
  /** True when the key name was inferred rather than directly read from the source PDF. */
  inferred: z.literal(true).optional(),
});

export type EluxConfigEntry = z.infer<typeof EluxConfigEntrySchema>;

const EluxConfigSchema = z.array(EluxConfigEntrySchema);

// ── Loading & caching ───────────────────────────────────────────────────────────

let cached: EluxConfigEntry[] | null = null;

/**
 * Loads and validates schema/elux-config.json. Throws a descriptive error if the file is
 * missing, malformed, or fails Zod validation. Result is cached after the first successful load.
 */
export function loadEluxConfigSchema(): EluxConfigEntry[] {
  if (cached) return cached;

  let raw: string;
  try {
    raw = readFileSync(SCHEMA_PATH, 'utf8');
  } catch (err) {
    throw new Error(
      `Failed to read eLux config schema at ${SCHEMA_PATH}. ` +
        `Run "npx tsx scripts/generate-elux-schema.ts" to (re)generate it. ` +
        `Underlying error: ${err instanceof Error ? err.message : String(err)}`,
    );
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(
      `eLux config schema at ${SCHEMA_PATH} is not valid JSON: ${err instanceof Error ? err.message : String(err)}`,
    );
  }

  const result = EluxConfigSchema.safeParse(parsed);
  if (!result.success) {
    throw new Error(`eLux config schema at ${SCHEMA_PATH} failed validation: ${result.error.message}`);
  }

  validateNoDuplicates(result.data);

  cached = result.data;
  return cached;
}

/** Throws if any `section.key` pair appears more than once in the schema. */
function validateNoDuplicates(entries: EluxConfigEntry[]): void {
  const seen = new Set<string>();
  for (const entry of entries) {
    const id = `${entry.section}.${entry.key}`;
    if (seen.has(id)) {
      throw new Error(`Duplicate eLux config schema entry for "${id}"`);
    }
    seen.add(id);
  }
}

/** Clears the in-memory cache. Exposed for tests that need to reload after regenerating the file. */
export function clearEluxConfigSchemaCache(): void {
  cached = null;
}

// ── Lookups ───────────────────────────────────────────────────────────────────────

/** Finds a single entry by exact section + key match, or undefined if not present. */
export function findEluxConfigEntry(section: string, key: string): EluxConfigEntry | undefined {
  return loadEluxConfigSchema().find((e) => e.section === section && e.key === key);
}

/** Returns all entries for a given section (case-sensitive, exact match). */
export function getEluxConfigSection(section: string): EluxConfigEntry[] {
  return loadEluxConfigSchema().filter((e) => e.section === section);
}

/** Returns the distinct list of section names present in the schema. */
export function listEluxConfigSections(): string[] {
  const sections = new Set(loadEluxConfigSchema().map((e) => e.section));
  return [...sections].sort();
}

/**
 * Returns true if `value` is within the documented range for the given entry. Used by
 * pre-write validation (§3) and RSoP's isExplicitDefault computation (§2). Returns true
 * (permissive) when the entry's range is a free-text type hint rather than an enumerable set,
 * since this loader does not attempt full type-string parsing (e.g. "a URL", "0-100").
 */
export function isValueInRange(entry: EluxConfigEntry, value: unknown): boolean {
  if (Array.isArray(entry.range)) {
    return entry.range.includes(value as string | number | boolean);
  }
  if (entry.range && typeof entry.range === 'object' && 'min' in entry.range && 'max' in entry.range) {
    return typeof value === 'number' && value >= entry.range.min && value <= entry.range.max;
  }
  // Free-text type hint or null range — cannot validate strictly, treat as permissive.
  return true;
}
